INSERT INTO `channel_message` VALUES (756, '6e678c01-9fdb-4f8c-ac1a-088b077c3bb2', 'USER', '李佩珊能領取哪些補助', NULL, NULL);
INSERT INTO `channel_message` VALUES (757, '6e678c01-9fdb-4f8c-ac1a-088b077c3bb2', 'AI', '根據李小潔的個案資料，以下是對可用政府補助政策的分析和推薦：\n\n### 1. 中低收入戶補助\n- **條件**：\n  - 家庭總收入分配全家人口平均每人每月低於最低生活費1.5倍（114年即2萬5,350元）。\n  - 全家人口之現金（含存款本金、利息）、有價證券、汽車及投資合計金額每人每年未超過15萬元。\n  - 全家人口之土地公告現值及房屋評定標準價格合計金額未超過675萬元。\n\n- **分析**：\n  - 李小潔的年收入約為12,400元，平均每月收入約1,033元，低於最低生活費1.5倍的標準，因此符合第一條件。\n  - 目前無法確認她的現金、投資及不動產狀況，因此無法確定是否符合第二和第三條件。\n\n### 2. 低收入戶補助\n- **條件**：\n  - 家庭總收入分配全家人口平均每人每月低於最低生活費（114年即1萬6,900元）。\n  - 全家人口之現金（含存款本金、利息）、有價證券、汽車及投資合計金額每人每年未超過10萬元。\n  - 全家人口之土地公告現值及房屋評定標準價格合計金額未超過450萬元。\n\n- **分析**：\n  - 李小潔的年收入約為12,400元，平均每月收入約1,033元，低於最低生活費的標準，因此符合第一條件。\n  - 目前無法確認她的現金、投資及不動產狀況，因此無法確定是否符合第二和第三條件。\n\n### 3. 身心障礙者生活補助\n- **條件**：\n  - 需領有身心障礙證明，且家庭總收入平均未達當年度每人每月最低生活費2.5倍，且未超過臺灣地區平均每人每月消費支出1.5倍者。\n  - 全家人口動產（含存款本金、投資、有價證券）未超過一定金額。\n  - 全家人口不動產（含房屋、土地）價值未超過臺灣省不動產限額2倍。\n\n- **分析**：\n  - 目前無法確認李小潔是否為身心障礙者，因此無法推薦此項補助。\n\n### 4. 緊急生活扶助\n- **條件**：\n  - 符合低收入戶的標準，且需在事實發生後6個月內提起申請。\n\n- **分析**：\n  - 若李小潔的生活陷入困境，且符合低收入戶的標準，則可以考慮申請此項補助。\n\n### 總結建議\n基於目前的資料，李小潔可能符合中低收入戶或低收入戶的補助條件，但需要進一步確認她的現金、投資及不動產狀況。建議她向當地社會福利機構申請評估，並提供所需的財務資料，以便獲得適當的補助。此外，如果她的生活陷入困境，則可以考慮申請緊急生活扶助。', NULL, NULL);
