INSERT INTO `channel_message` VALUES (949, 'db92aff4-8ca7-4315-a4fd-cdc995cda28e', 'AI', '根據吳靜怡的個案資料，以下是對其年收入和月收入的整理，以及對可用政府補助的分析：\n\n### 一、年收入與月收入整理\n\n1. **月收入**：\n   - 低收入戶生活補助：7200元\n   - 偶爾接翻譯工作：約10000元（假設每月都有此收入）\n   - **總月收入**：7200元 + 10000元 = 17200元\n\n2. **年收入**：\n   - 低收入戶生活補助：7200元 × 12 = 86400元\n   - 鼓勵金：2000元\n   - 存款利息：300元\n   - 偶爾接翻譯工作：約10000元 × 12 = 120000元\n   - **總年收入**：86400元 + 2000元 + 300元 + 120000元 = 302700元\n\n### 二、補助政策分析\n\n1. **中低收入戶身心障礙者補助**：\n   - 每人每月補助新臺幣4,049元（輕度者）或5,437元（中重度者）。\n   - **符合條件**：吳靜怡沒有身心障礙的證明，因此不符合此項補助。\n\n2. **中低收入戶滿65歲老人補助**：\n   - 每人每月補助新臺幣8,329元。\n   - **符合條件**：吳靜怡未滿65歲，因此不符合此項補助。\n\n3. **全民健保自付保險費補助**：\n   - 補助全民健保自付保險費二分之一。\n   - 吳靜怡每年繳費3600元，則每月自付保險費為3600元 / 12 = 300元。\n   - 補助金額為300元 / 2 = 150元。\n   - **符合條件**：吳靜怡符合中低收入戶的身份，因此可以申請此項補助。\n\n4. **未滿18歲之兒童少年補助**：\n   - 補助全民健保自付保險費全額。\n   - **符合條件**：吳靜怡沒有未滿18歲的兒童，因此不符合此項補助。\n\n### 三、推薦的補助\n\n根據以上分析，吳靜怡符合的補助政策為：\n\n- **全民健保自付保險費補助**：每月可獲得150元的補助。\n\n### 總結\n\n吳靜怡的年收入為302700元，月收入為17200元。根據她的身份狀況，唯一符合的政府補助為全民健保自付保險費的補助，每月可獲得150元。建議她向相關單位申請此項補助以減輕經濟負擔。', NULL, NULL);
