INSERT INTO `channel_message` VALUES (952, '4fc50e3f-c485-427d-ba33-6f5e5fe7c0a2', 'USER', '吳靜怡個案能領取的補助', NULL, NULL);
INSERT INTO `channel_message` VALUES (953, '4fc50e3f-c485-427d-ba33-6f5e5fe7c0a2', 'AI', '### 個案年收入與月收入整理\n\n#### 年收入\n根據個案資料，吳靜怡的年收入來源如下：\n- 年終獎金：8000元 + 5500元 = 13500元\n- 存款利息：500元\n\n因此，吳靜怡的年收入總計為：\n- **年收入** = 13500元 + 500元 = **14000元**\n\n#### 月收入\n將年收入轉換為月收入：\n- **月收入** = 14000元 / 12 = **1166.67元**\n\n### 補助政策分析\n\n1. **中低收入戶生活補助**\n   - **補助金額**：每人每月補助新臺幣4,049元（輕度身心障礙者）或5,437元（中重度身心障礙者）。\n   - **條件**：\n     - 家庭總收入分配全家人口平均每人每月低於最低生活費1.5倍（114年即2萬5,350元）。\n     - 全家人口之現金（含存款本金、利息）、有價證券、汽車及投資合計金額每人每年未超過15萬元。\n     - 全家人口之土地公告現值及房屋評定標準價格合計金額未超過675萬元。\n   - **分析**：\n     - 吳靜怡的月收入1166.67元，低於最低生活費1.5倍（25,350元），符合條件。\n     - 吳靜怡的資產（車輛500,000元 + 貴重金屬180,000元 + 收藏品90,000元 = 770,000元）超過15萬元，因此不符合該項補助的資產條件。\n   - **結論**：不符合該項補助條件。\n\n2. **老年人補助**\n   - **補助金額**：每人每月補助新臺幣8,329元。\n   - **條件**：滿65歲老人。\n   - **分析**：吳靜怡出生於1966年04月04日，年齡尚未滿65歲（2025年時為58歲），因此不符合該項補助條件。\n   - **結論**：不符合該項補助條件。\n\n3. **全民健保自付保險費補助**\n   - **補助金額**：補助全民健保自付保險費二分之一。\n   - **條件**：列冊中低收入戶。\n   - **分析**：吳靜怡目前已申請新北市低收入戶生活補助，符合中低收入戶的身份。\n   - **結論**：符合該項補助條件。\n\n4. **未滿18歲之兒童少年補助**\n   - **補助金額**：補助全民健保自付保險費全額。\n   - **條件**：未滿18歲之兒童少年。\n   - **分析**：吳靜怡並不符合該條件（年齡58歲）。\n   - **結論**：不符合該項補助條件。\n\n### 總結\n根據以上分析，吳靜怡符合的政府補助為：\n- **全民健保自付保險費補助**（因為他已申請低收入戶生活補助）。\n\n其他補助政策均不符合條件。建議吳靜怡進一步了解全民健保自付保險費補助的申請流程，以獲得相應的支持。', NULL, NULL);
INSERT INTO `channel_message` VALUES (954, 'aaa6e205-d42c-4696-8b42-b5ed8ddc0870', 'USER', '林鴻隆個案能領取的補助', NULL, NULL);
INSERT INTO `channel_message` VALUES (955, 'aaa6e205-d42c-4696-8b42-b5ed8ddc0870', 'AI', '### 個案年收入與月收入整理\n\n#### 年收入\n- 每月薪資: 400,000元\n- 年終獎金: 100元\n\n計算年收入：\n- 年收入 = 每月薪資 × 12 + 年終獎金\n- 年收入 = 400,000元 × 12 + 100元 = 4,800,100元\n\n#### 月收入\n- 月收入 = 每月薪資 = 400,000元\n\n### 補助政策分析\n\n#### 1. 中低收入戶補助\n- **條件**：\n  1. 家庭總收入分配全家人口平均每人每月低於最低生活費1.5倍（114年即2萬5,350元）。\n  2. 全家人口之現金（含存款本金、利息）、有價證券、汽車及投資合計金額每人每年未超過15萬元。\n  3. 全家人口之土地公告現值及房屋評定標準價格合計金額未超過675萬元。\n\n- **分析**：\n  - 林鴻隆的年收入為4,800,100元，月收入為400,000元，顯然超過了最低生活費1.5倍的標準，因此不符合第一條件。\n  - 由於不符合第一條件，無法推薦此項補助。\n\n#### 2. 身心障礙者補助\n- **條件**：\n  - 列冊中低收入戶為身心障礙者，輕度者，每人每月補助新臺幣4,049元、中重度以上者，每人每補助新臺幣5,437元。\n\n- **分析**：\n  - 林鴻隆並不具有身心障礙，因此不符合此項補助的條件。\n\n#### 3. 老人補助\n- **條件**：\n  - 列冊中低收入戶，滿65歲老人，每人每月補助新臺幣8,329元。\n\n- **分析**：\n  - 林鴻隆出生於1970年，年齡為53歲，未滿65歲，因此不符合此項補助的條件。\n\n#### 4. 全民健保自付保險費補助\n- **條件**：\n  - 補助全民健保自付保險費二分之一。\n\n- **分析**：\n  - 此項補助通常針對中低收入戶，林鴻隆符合中低收入戶的身份，但因為其年收入超過了中低收入戶的標準，因此不符合此項補助的條件。\n\n#### 5. 兒童少年補助\n- **條件**：\n  - 未滿18歲之兒童少年，補助全民健保自付保險費全額。\n\n- **分析**：\n  - 林鴻隆並未提及有未滿18歲的兒童，因此不符合此項補助的條件。\n\n### 總結\n根據林鴻隆的年收入、月收入及各項補助政策的條件分析，林鴻隆不符合任何可用的政府補助政策。', NULL, NULL);
INSERT INTO `channel_message` VALUES (956, '692300be-d782-4731-b6cb-5d54a8b877af', 'USER', '李佩珊個案能領取的補助', NULL, NULL);
INSERT INTO `channel_message` VALUES (957, '692300be-d782-4731-b6cb-5d54a8b877af', 'AI', '### 個案年收入與月收入整理\n\n#### 年收入\n根據李佩珊的收入資料，2024年度的薪資和其他收入如下：\n\n- **薪資**:\n  - 2024年1月: 13500元\n  - 2024年2月: 13500元\n  - 2024年3月: 13500元\n  - 2024年4月: 7000元\n  - 2024年5月: 7000元\n  - 2024年6月: 7000元\n  - 2024年7月: 7000元\n  - 2024年8月: 7000元\n  - 2024年9月: 13500元\n  - 2024年10月: 7000元\n  - 2024年11月: 3850元\n  - 2024年12月: 8495元\n\n- **其他收入**:\n  - 2024年1月: 7000元\n  - 2024年2月: 7000元\n  - 2024年3月: 300元\n  - 2024年4月: 7000元\n  - 2024年5月: 7000元\n  - 2024年6月: 7000元\n  - 2024年7月: 7000元\n  - 2024年8月: 7000元\n  - 2024年9月: 7000元\n  - 2024年10月: 7000元\n  - 2024年11月: 7000元\n  - 2024年12月: 7000元\n\n#### 總收入計算\n- **薪資總和**: 13500 * 3 + 7000 * 8 + 3850 + 8495 = 162000 + 56000 + 3850 + 8495 = 224345元\n- **其他收入總和**: 7000 * 10 + 300 + 7000 * 2 = 70000 + 300 + 14000 = 81400元\n\n- **年收入總和**: 224345 + 81400 = 305745元\n\n#### 月收入\n- **月收入**: 305745元 / 12 = 25478.75元\n\n### 補助政策分析\n\n1. **中低收入戶補助**:\n   - **條件**:\n     - 家庭總收入分配全家人口平均每人每月低於最低生活費1.5倍。\n     - 全家人口之現金、證券、汽車及投資合計金額每人每年未超過15萬元。\n     - 全家人口之土地公告現值及房屋評定標準價格合計金額未超過675萬元。\n   - **分析**:\n     - 李佩珊的月收入為25478.75元，超過最低生活費1.5倍的標準（25350元），因此不符合此項補助的條件。\n\n2. **身心障礙者補助**:\n   - **條件**: 需為身心障礙者。\n   - **分析**: 李佩珊並不具有身心障礙，因此不符合此項補助的條件。\n\n3. **65歲以上老人補助**:\n   - **條件**: 需年滿65歲。\n   - **分析**: 李佩珊出生於2025年，尚未滿65歲，因此不符合此項補助的條件。\n\n4. **全民健保自付保險費補助**:\n   - **條件**: 需為中低收入戶。\n   - **分析**: 由於李佩珊不符合中低收入戶的條件，因此不符合此項補助的條件。\n\n5. **未滿18歲之兒童少年補助**:\n   - **條件**: 需未滿18歲。\n   - **分析**: 李佩珊出生於2025年，尚未滿18歲，因此符合此項補助的條件。\n\n### 總結\n根據以上分析，李佩珊的年收入為305745元，月收入為25478.75元。她不符合中低收入戶、身心障礙者、65歲以上老人及全民健保自付保險費補助的條件，但符合未滿18歲之兒童少年補助的條件。建議推薦她申請未滿18歲之兒童少年補助。', NULL, NULL);
INSERT INTO `channel_message` VALUES (958, 'fc44c211-c2b5-4b74-9635-a80bb1f99697', 'USER', '李佩珊個案風險評估', NULL, NULL);
INSERT INTO `channel_message` VALUES (959, 'fc44c211-c2b5-4b74-9635-a80bb1f99697', 'AI', '### 個案分析\n\n#### 入不敷出的因素\n1. **收入不穩定**: 李佩珊的收入來源主要來自於臨時促銷員的工作，這種工作性質使得她的收入不穩定，尤其在某些月份的收入大幅下降（如4月、5月和7月的收入僅7000元），無法穩定支撐生活開支。\n\n2. **支出過高**: 在2024年1月，李佩珊的支出達到40000元，這遠高於她的收入20500元，造成了巨大的財務壓力。即使在其他月份，支出也普遍高於收入，特別是在收入較低的月份。\n\n3. **缺乏儲蓄**: 李佩珊的財務記錄顯示，她幾乎沒有儲蓄，這使得她在面對突發支出或收入減少時，無法應對。\n\n4. **依賴補助**: 雖然她有低收入戶生活補助，但這僅能部分緩解她的經濟壓力，無法根本解決入不敷出的問題。\n\n5. **投資風險**: 李佩珊有股票投資，但目前的持股狀況和市場波動可能會影響她的財務狀況，尤其是如果這些投資未能帶來穩定的回報。\n\n#### 改善建議\n1. **尋找穩定工作**: 建議李佩珊尋找更穩定的工作機會，避免依賴臨時工作，這樣可以提高收入的穩定性。\n\n2. **制定預算計劃**: 建議她制定詳細的預算計劃，控制每月的支出，特別是非必要的開支，確保支出不超過收入。\n\n3. **建立緊急基金**: 儘量儲蓄一部分收入，建立緊急基金，以應對突發的財務需求，建議目標為至少三個月的生活費用。\n\n4. **提升技能**: 考慮參加職業培訓或進修課程，提升自身技能，增加未來的就業機會和收入潛力。\n\n5. **評估投資風險**: 定期檢視投資組合，根據市場狀況調整投資策略，避免過度依賴高風險的投資。\n\n6. **尋求專業財務諮詢**: 如果可能，尋求專業的財務顧問協助，制定長期的財務計劃，幫助她更好地管理財務狀況。\n\n透過以上建議，李佩珊可以逐步改善她的財務狀況，減少入不敷出的情況。', NULL, NULL);
