INSERT INTO `channel_message` VALUES (962, '4c38184f-0113-4700-9c18-8a8097a4958a', 'USER', '吳靜怡個案風險評估', NULL, NULL);
INSERT INTO `channel_message` VALUES (963, '4c38184f-0113-4700-9c18-8a8097a4958a', 'AI', '根據吳靜怡的個案資料，我們可以分析出幾個因素使其入不敷出，並提出改善建議。\n\n### 1. 收入不足\n- **年收入**: 吳靜怡的年終獎金和存款利息總共只有13500元，加上低收入戶生活補助5000元，年收入總計18500元，這對於生活開支來說是相對較低的。\n\n### 2. 高額支出\n- **支出項目**: 吳靜怡的支出包括交通稅500元、房屋稅5000元和地價稅9000元，總計10500元。這些稅費佔據了其收入的很大一部分，導致入不敷出。\n\n### 3. 負債壓力\n- **負債項目**: 吳靜怡有消費型貸款85000元和汽車貸款200000元，這些負債會產生利息，進一步加重其財務負擔。\n\n### 4. 投資風險\n- **股票投資**: 吳靜怡持有的股票數量不多，且購買價格較高，若市場波動，可能面臨虧損的風險。\n\n### 改善建議\n1. **增加收入來源**:\n   - 考慮尋找兼職工作或技能提升，增加收入來源。\n   - 參加社區或政府提供的職業培訓，提升就業能力。\n\n2. **減少支出**:\n   - 檢視生活開支，尋找可削減的項目，例如交通費用或其他非必要開支。\n   - 考慮申請其他社會福利或補助，減輕生活負擔。\n\n3. **管理負債**:\n   - 與貸款機構協商，尋求降低利率或延長還款期限的可能性。\n   - 優先償還高利貸款，減少利息支出。\n\n4. **投資策略調整**:\n   - 考慮將部分資金轉向風險較低的投資工具，例如定存或債券，降低投資風險。\n   - 定期檢視投資組合，根據市場情況調整持倉。\n\n5. **建立緊急基金**:\n   - 儘量每月儲蓄一小部分收入，建立緊急基金，以應對突發的財務需求。\n\n透過以上的改善建議，吳靜怡可以逐步改善其財務狀況，減少入不敷出的情況。', NULL, NULL);
INSERT INTO `channel_message` VALUES (966, '062781bd-0576-4a6a-b6be-5e9dd79f9028', 'USER', '李佩珊個案能領取的補助', NULL, NULL);
INSERT INTO `channel_message` VALUES (967, '062781bd-0576-4a6a-b6be-5e9dd79f9028', 'AI', '### 個案年收入與月收入整理\n\n#### 年收入計算\n根據李佩珊的收入資料，計算她的年收入如下：\n\n- **薪資收入**：\n  - 2024年1月: 13500元\n  - 2024年2月: 13500元\n  - 2024年3月: 13500元\n  - 2024年4月: 7000元\n  - 2024年5月: 7000元\n  - 2024年6月: 7000元\n  - 2024年7月: 7000元\n  - 2024年8月: 7000元\n  - 2024年9月: 13500元\n  - 2024年10月: 7000元\n  - 2024年11月: 3850元\n  - 2024年12月: 8495元\n\n  總薪資收入 = 13500 + 13500 + 13500 + 7000 + 7000 + 7000 + 7000 + 7000 + 13500 + 7000 + 3850 + 8495 = 103,845元\n\n- **其他收入**：\n  - 每月: 7000元 (部分月份)\n  - 2024年1月: 7000元\n  - 2024年2月: 7000元\n  - 2024年3月: 300元\n  - 2024年4月: 7000元\n  - 2024年5月: 7000元\n  - 2024年6月: 7000元\n  - 2024年7月: 7000元\n  - 2024年8月: 7000元\n  - 2024年9月: 7000元\n  - 2024年10月: 7000元\n  - 2024年11月: 7000元\n  - 2024年12月: 7000元\n\n  總其他收入 = 7000 * 11 + 300 = 77,300元\n\n- **股息分配**：560元\n\n#### 總年收入\n總年收入 = 總薪資收入 + 總其他收入 + 股息分配 = 103,845 + 77,300 + 560 = 181,705元\n\n#### 月收入計算\n月收入 = 總年收入 / 12 = 181,705 / 12 ≈ 15,142元\n\n### 補助政策分析\n\n1. **低收入戶生活補助**：\n   - **金額**: 7000元\n   - **申請時間**: 2018年06月03日\n   - **預定領取時間**: 2025年05月03日\n   - **符合條件**: 李佩珊已經是低收入戶，並且正在領取該補助。\n\n2. **身心障礙者補助**：\n   - **金額**: 輕度者每人每月補助新臺幣4,049元，中重度以上者每人每月補助新臺幣5,437元。\n   - **符合條件**: 李佩珊並不具有身心障礙，因此不符合該項補助。\n\n3. **65歲以上老人補助**：\n   - **金額**: 每人每月補助新臺幣8,329元。\n   - **符合條件**: 李佩珊年齡尚未滿65歲，因此不符合該項補助。\n\n4. **全民健保自付保險費補助**：\n   - **金額**: 補助自付保險費二分之一。\n   - **符合條件**: 李佩珊的醫療險保險狀況未提供具體的自付金額，因此無法判斷是否符合該項補助。\n\n5. **未滿18歲之兒童少年補助**：\n   - **金額**: 補助全民健保自付保險費全額。\n   - **符合條件**: 李佩珊已滿18歲，因此不符合該項補助。\n\n### 總結\n根據以上分析，李佩珊符合的補助政策為「低收入戶生活補助」，並且已經在領取該補助。其他補助政策因不符合條件而無法推薦。', NULL, NULL);
INSERT INTO `channel_message` VALUES (968, '4428e618-897b-4394-a6b4-62626854b635', 'USER', '吳靜怡個案能領取的補助', NULL, NULL);
INSERT INTO `channel_message` VALUES (969, '4428e618-897b-4394-a6b4-62626854b635', 'AI', '### 個案年收入與月收入整理\n\n#### 年收入計算\n根據個案資料，吳靜怡的年收入來源如下：\n- 年終獎金1: 8000元\n- 年終獎金2: 5500元\n- 存款利息: 500元\n\n**年收入總計**：\n8000 + 5500 + 500 = 14000元\n\n#### 月收入計算\n**月收入**：\n年收入14000元 ÷ 12個月 = 約1166.67元\n\n### 補助政策分析\n\n#### 1. 低收入戶生活補助\n- **補助名稱**: 新北市低收入戶生活補助\n- **金額**: 5000元\n- **申請時間**: 2025年04月07日\n- **領取時間**: 2025年04月07日\n\n**符合條件**：\n吳靜怡已經申請並獲得此補助，因此不需要再次評估。\n\n#### 2. 身心障礙者補助\n- **補助金額**: 輕度者每人每月補助新臺幣4,049元，中重度以上者每人每月補助新臺幣5,437元。\n\n**不符合條件**：\n吳靜怡並未被認定為身心障礙者，因此不符合此項補助的申請條件。\n\n#### 3. 老人補助\n- **補助金額**: 滿65歲老人每人每月補助新臺幣8,329元。\n\n**不符合條件**：\n吳靜怡目前年齡為57歲，尚未滿65歲，因此不符合此項補助的申請條件。\n\n#### 4. 全民健保自付保險費補助\n- **補助內容**: 補助全民健保自付保險費二分之一。\n\n**不符合條件**：\n吳靜怡的保險狀況中並未提及其自付保險費的具體金額，因此無法評估是否符合此項補助的申請條件。\n\n#### 5. 兒童少年補助\n- **補助內容**: 未滿18歲之兒童少年，補助全民健保自付保險費全額。\n\n**不符合條件**：\n吳靜怡已年滿57歲，並不符合此項補助的申請條件。\n\n### 總結\n根據以上分析，吳靜怡目前符合的補助為新北市低收入戶生活補助，並已成功申請。其他補助項目均不符合申請條件。', NULL, NULL);
INSERT INTO `channel_message` VALUES (972, '25a7928a-955a-4565-b850-daa0e0c29243', 'USER', '林鴻隆個案能領取的補助', NULL, NULL);
INSERT INTO `channel_message` VALUES (973, '25a7928a-955a-4565-b850-daa0e0c29243', 'AI', '### 個案年收入與月收入整理\n\n#### 年收入\n- 每月薪資: 400,000元\n- 年終獎金: 100元\n\n計算年收入：\n- 年收入 = 每月薪資 × 12 + 年終獎金\n- 年收入 = 400,000元 × 12 + 100元 = 4,800,100元\n\n#### 月收入\n- 每月薪資: 400,000元\n\n### 補助政策分析\n\n根據個案資料，林鴻隆的年收入為4,800,100元，月收入為400,000元。接下來，我們將分析可用的補助政策。\n\n#### 補助政策分析\n1. **天涯1**\n   - 金額: 1,000元\n   - 申請時間: 2025年03月29日\n   - 領取時間: 2025年03月29日\n   - **符合條件**: 是，因為已經申請並領取。\n\n2. **天涯3**\n   - 金額: 1,000元\n   - 申請時間: 2025年03月29日\n   - 領取時間: 2025年03月29日\n   - **符合條件**: 是，因為已經申請並領取。\n\n3. **天涯2899**\n   - 金額: 89元\n   - 申請時間: 2025年03月29日\n   - 領取時間: 2025年03月29日\n   - **符合條件**: 是，因為已經申請並領取。\n\n### 總結\n根據林鴻隆的年收入和月收入，雖然他可能符合中低收入戶的標準，但由於其實際收入相對較高，可能不符合其他政府補助的申請條件。根據目前的補助記錄，他已經成功申請並領取了三項補助（天涯1、天涯3、天涯2899），這些補助已經是他目前能夠獲得的支持。若未來有其他補助政策出現，建議持續關注並評估其符合性。', NULL, NULL);
INSERT INTO `channel_message` VALUES (980, 'a35796b0-7804-4563-b786-d338ead80910', 'USER', '黃文雄個案能領取的補助', NULL, NULL);
INSERT INTO `channel_message` VALUES (981, 'a35796b0-7804-4563-b786-d338ead80910', 'AI', '### 個案年收入與月收入整理\n\n#### 月收入\n- 夜市攤位收入：14,000 元\n- 每月補助：8,000 元\n- **總月收入**：22,000 元\n\n#### 年收入\n- **年收入**：22,000 元 × 12 個月 = 264,000 元\n\n### 補助政策分析\n\n根據個案的資料，黃文雄符合以下條件：\n\n1. **身心障礙者補助**：\n   - **福利說明**：針對具有身心障礙的個人提供的經濟補助，旨在協助其生活及醫療需求。\n   - **符合條件**：黃文雄具有身心障礙身份，並且擁有相關的福利證明，因此符合申請條件。\n\n2. **低收入戶補助**（若適用）：\n   - **福利說明**：針對中低收入戶提供的生活補助，幫助其改善生活品質。\n   - **符合條件**：目前資料中未提供是否為中低收入戶的具體信息，因此無法確定是否符合該項補助的申請條件。\n\n### 總結推薦\n\n基於以上分析，黃文雄可以申請的補助為：\n\n- **身心障礙者補助**：因為他符合身心障礙者的身份要求，並擁有相關的福利證明。\n\n對於低收入戶補助，因為缺乏相關的收入資料，無法確定是否符合申請條件，因此不予推薦。建議進一步確認其家庭收入狀況，以便評估是否符合低收入戶的標準。', NULL, NULL);
INSERT INTO `channel_message` VALUES (1002, '6160112c-3333-4fa2-93e0-1e1ef2dd927c', 'USER', '楊世豪個案能領取的補助', NULL, NULL);
INSERT INTO `channel_message` VALUES (1003, '6160112c-3333-4fa2-93e0-1e1ef2dd927c', 'AI', '### 個案年收入與月收入計算\n\n#### 收入來源\n- **職業收入**: 臨時貨運司機（具體金額未提供）\n- **其他收入**: 1805元\n- **股息分配**: 4976元\n\n#### 年收入計算\n由於缺乏臨時貨運司機的具體收入數據，無法準確計算年收入。根據其他收入和股息分配的數據：\n- **其他收入**: 1805元 × 12 = 21660元\n- **股息分配**: 4976元 × 12 = 59712元\n\n因此，年收入的總和為：\n- **年收入** = 21660元 + 59712元 = 81372元\n\n#### 月收入計算\n- **月收入** = 年收入 / 12 = 81372元 / 12 ≈ 6781元\n\n### 補助政策分析\n\n#### 1. 新北市低收入戶生活補助\n- **金額**: 7800元\n- **申請時間**: 2025年01月01日\n- **領取時間**: 2025年05月05日\n\n##### 福利說明\n- 此補助針對低收入戶提供生活補助，申請者必須符合低收入戶的標準。\n\n##### 符合條件分析\n- **是否為低收入戶**: 根據個案的年收入81372元，月收入約6781元，這可能符合新北市低收入戶的標準（具體標準需查詢當地政府的最新規定）。\n- **是否有福利身分證明**: 是\n- **是否為原住民或新住民**: 是\n\n#### 結論\n根據以上分析，楊世豪符合新北市低收入戶生活補助的申請條件，建議他繼續申請該項補助。\n\n### 總結\n- **年收入**: 81372元\n- **月收入**: 約6781元\n- **推薦補助**: 新北市低收入戶生活補助（7800元）', NULL, NULL);
INSERT INTO `channel_message` VALUES (1004, 'c40ce489-c192-4d44-bfc4-5706b763d078', 'USER', '楊世豪個案能領取的補助', NULL, NULL);
INSERT INTO `channel_message` VALUES (1005, 'c40ce489-c192-4d44-bfc4-5706b763d078', 'AI', '### 個案年收入與月收入計算\n\n#### 收入來源\n- **職業收入**: 臨時貨運司機（具體金額未提供）\n- **其他收入**: 1805元\n- **股息分配**: 4976元\n\n#### 年收入計算\n由於缺乏臨時貨運司機的具體收入數據，無法準確計算年收入。根據其他收入和股息分配的數據：\n- **其他收入**: 1805元 × 12 = 21660元\n- **股息分配**: 4976元 × 12 = 59712元\n\n因此，年收入的部分可以計算為：\n- **年收入（不包括職業收入）**: 21660元 + 59712元 = 81372元\n\n#### 月收入計算\n- **月收入（不包括職業收入）**: (21660元 + 59712元) / 12 = 6781元\n\n### 補助政策分析\n\n#### 1. 新北市低收入戶生活補助\n- **金額**: 7800元\n- **申請時間**: 2025年01月01日\n- **領取時間**: 2025年05月05日\n\n##### 福利説明\n- 申請者必須為低收入戶，且需具備相關的福利身分證明。\n- 申請者的家庭收入必須低於新北市政府所規定的低收入戶標準。\n\n##### 符合條件分析\n- **是否為低收入戶**: 是，因為已經獲得7800元的生活補助。\n- **是否有福利身分證明**: 是。\n\n因此，楊世豪符合新北市低收入戶生活補助的申請條件。\n\n### 總結\n根據以上分析，楊世豪的年收入為81372元，月收入為6781元。根據目前的資料，他符合新北市低收入戶生活補助的申請條件，並且已經在2025年01月01日申請並於2025年05月05日領取7800元的生活補助。其他補助政策未提供具體資料或不符合申請條件，因此不予推薦。', NULL, NULL);
INSERT INTO `channel_message` VALUES (1006, 'c40ce489-c192-4d44-bfc4-5706b763d078', 'USER', '沒有原住民補助可以領?', NULL, NULL);
INSERT INTO `channel_message` VALUES (1007, 'c40ce489-c192-4d44-bfc4-5706b763d078', 'AI', '### 個案年收入與月收入整理\n\n#### 年收入\n根據個案資料，楊世豪的收入來源如下：\n- 其他收入：1805元\n- 股息分配：4976元\n- 月金額：4000元\n- 新北市低收入戶生活補助：7800元（已申請）\n\n計算年收入：\n- 其他收入：1805元 × 12 = 21660元\n- 股息分配：4976元 × 12 = 59712元\n- 月金額：4000元 × 12 = 48000元\n- 低收入戶生活補助：7800元 × 12 = 93600元\n\n**總年收入 = 21660 + 59712 + 48000 + 93600 = 222972元**\n\n#### 月收入\n根據上述計算，楊世豪的月收入為：\n- 其他收入：1805元\n- 股息分配：4976元\n- 月金額：4000元\n- 低收入戶生活補助：7800元\n\n**總月收入 = 1805 + 4976 + 4000 + 7800 = 18581元**\n\n### 補助政策分析\n\n1. **中低收入戶補助**\n   - **條件**：\n     - 家庭總收入分配全家人口平均每人每月低於最低生活費1.5倍（114年即2萬5,350元）。\n     - 全家人口之現金、證券、汽車及投資合計金額每人每年未超過15萬元。\n     - 全家人口之土地公告現值及房屋評定標準價格合計金額未超過675萬元。\n   - **分析**：\n     - 楊世豪的月收入18581元，低於2萬5,350元，因此符合第一條件。\n     - 他的資產（車輛價值12000元 + 50000元 = 62000元）和投資（25000元）合計為87000元，未超過15萬元，因此符合第二條件。\n     - 由於未提供土地和房屋的相關資料，無法判斷第三條件是否符合。\n   - **結論**：若第三條件符合，則可推薦此補助。\n\n2. **身心障礙者補助**\n   - **條件**：\n     - 列冊中低收入戶為身心障礙者，輕度者每人每月補助新臺幣4,049元，中重度以上者每人每月補助新臺幣5,437元。\n   - **分析**：\n     - 楊世豪並不具有身心障礙，因此不符合此項補助的條件。\n   - **結論**：不推薦此補助。\n\n3. **老人補助**\n   - **條件**：\n     - 列冊中低收入戶，滿65歲老人每人每月補助新臺幣8,329元。\n   - **分析**：\n     - 楊世豪出生於2025年，尚未滿65歲，因此不符合此項補助的條件。\n   - **結論**：不推薦此補助。\n\n4. **全民健保自付保險費補助**\n   - **條件**：\n     - 補助全民健保自付保險費二分之一。\n   - **分析**：\n     - 需確認楊世豪是否有自付的健保費用，若有則可申請此補助。\n   - **結論**：若有自付健保費用，則可推薦此補助。\n\n5. **未滿18歲之兒童少年補助**\n   - **條件**：\n     - 補助全民健保自付保險費全額。\n   - **分析**：\n     - 楊世豪已滿18歲，因此不符合此項補助的條件。\n   - **結論**：不推薦此補助。\n\n### 總結推薦\n根據以上分析，楊世豪符合以下補助的條件：\n- **中低收入戶補助**（若土地和房屋條件符合）\n- **全民健保自付保險費補助**（若有自付健保費用）\n\n建議進一步確認土地和房屋的相關資料，以便確定是否符合中低收入戶補助的第三條件。', NULL, NULL);
INSERT INTO `channel_message` VALUES (1008, 'c40ce489-c192-4d44-bfc4-5706b763d078', 'USER', '沒有原住民補助可以領?', NULL, NULL);
INSERT INTO `channel_message` VALUES (1009, 'c40ce489-c192-4d44-bfc4-5706b763d078', 'AI', '### 個案年收入與月收入計算\n\n#### 收入來源\n- **職業收入**: 臨時貨運司機（具體金額未提供）\n- **其他收入**: 1805元\n- **股息分配**: 4976元\n\n#### 年收入計算\n由於缺乏臨時貨運司機的具體收入數據，無法準確計算年收入。根據其他收入和股息分配的數據：\n- **其他收入**: 1805元 × 12 = 21660元\n- **股息分配**: 4976元 × 12 = 59712元\n\n因此，年收入的部分可以計算為：\n- **年收入（不包括職業收入）**: 21660元 + 59712元 = 81372元\n\n#### 月收入計算\n- **月收入（不包括職業收入）**: 1805元 + 4976元 = 6781元\n\n### 補助政策分析\n\n#### 1. 新北市低收入戶生活補助\n- **金額**: 7800元\n- **申請時間**: 2025年01月01日\n- **領取時間**: 2025年05月05日\n\n##### 福利説明\n- **適用對象**: 低收入戶\n- **條件**: 需具備低收入戶身份，且家庭收入需低於政府規定的標準。\n\n##### 符合性分析\n- 楊世豪已經申請並獲得新北市低收入戶生活補助，符合該項補助的所有條件。\n\n### 總結\n根據以上分析，楊世豪的年收入為81372元，月收入為6781元。由於他已經獲得新北市低收入戶生活補助，因此不需要再推薦其他補助。若未來有其他補助政策或變更，建議持續關注相關資訊。', NULL, NULL);
INSERT INTO `channel_message` VALUES (1010, 'c40ce489-c192-4d44-bfc4-5706b763d078', 'USER', '為什麼他是原住民 沒有辦法領原住民補助', NULL, NULL);
INSERT INTO `channel_message` VALUES (1011, 'c40ce489-c192-4d44-bfc4-5706b763d078', 'AI', '### 個案年收入與月收入計算\n\n#### 收入來源\n- **職業收入**: 臨時貨運司機（具體金額未提供）\n- **其他收入**: 1805元\n- **股息分配**: 4976元\n\n#### 年收入計算\n由於缺乏臨時貨運司機的具體收入數據，無法準確計算年收入。以下是已知收入的計算：\n\n- **其他收入**: 1805元 * 12 = 21660元\n- **股息分配**: 4976元 * 12 = 59712元\n\n#### 總年收入\n- **總年收入** = 21660元 + 59712元 = 81372元\n\n#### 月收入計算\n- **月收入** = 總年收入 / 12 = 81372元 / 12 ≈ 6781元\n\n### 補助政策分析\n\n#### 1. 新北市低收入戶生活補助\n- **金額**: 7800元\n- **申請時間**: 2025年01月01日\n- **領取時間**: 2025年05月05日\n\n##### 福利説明\n- 針對低收入戶提供的生活補助，旨在協助經濟困難的家庭，幫助他們維持基本生活需求。\n\n##### 符合條件\n- **是否為低收入戶**: 根據個案的年收入81372元，月收入約6781元，符合低收入戶的標準（新北市低收入戶的標準通常是月收入低於某一金額，具體金額需查詢當地政策）。\n- **是否有福利身分證明**: 是\n- **是否為原住民或新住民**: 是\n\n#### 結論\n根據以上分析，楊世豪符合新北市低收入戶生活補助的申請條件，並且已經在2025年01月01日申請，預計在2025年05月05日領取7800元的補助。\n\n### 總結\n- **年收入**: 81372元\n- **月收入**: 約6781元\n- **推薦補助**: 新北市低收入戶生活補助（已申請，預計領取7800元）', NULL, NULL);
