INSERT INTO `channel_message` VALUES (1013, '706087d7-57e9-4435-a98c-e3899c06b146', 'AI', '### 個案年收入與月收入計算\n\n#### 年收入\n- **職業收入**: 由於個案的職業為臨時貨運司機，未提供具體的年收入數字，因此無法計算。\n- **其他收入**: 1805元 * 12 = 21660元\n- **股息分配**: 4976元 * 12 = 59712元\n\n**年收入總計**: \n- 職業收入: 無法計算\n- 其他收入: 21660元\n- 股息分配: 59712元\n\n**年收入合計**: 21660 + 59712 = 81372元（不包括職業收入）\n\n#### 月收入\n- **其他收入**: 1805元\n- **股息分配**: 4976元\n\n**月收入總計**: \n- 其他收入: 1805元\n- 股息分配: 4976元\n\n**月收入合計**: 1805 + 4976 = 6781元\n\n### 補助政策分析\n\n#### 1. 新北市低收入戶生活補助\n- **金額**: 7800元\n- **申請時間**: 2025年01月01日\n- **領取時間**: 2025年05月05日\n\n**福利説明**:\n- 針對低收入戶提供的生活補助，申請者必須符合低收入戶的標準。\n\n**符合條件**:\n- 個案已經申請並獲得此補助，符合低收入戶的標準。\n\n### 總結\n根據個案的資料，楊世豪目前已經獲得了新北市低收入戶生活補助7800元，符合該補助的所有條件。由於未提供具體的職業收入數字，無法進一步推薦其他補助。建議持續關注其他可能的補助政策，特別是針對原住民或新住民的相關福利。', NULL, NULL);
INSERT INTO `channel_message` VALUES (1030, '0fb7cedf-b648-427f-9269-ce2fdf989f06', 'USER', '張惠萍個案能領取的補助', NULL, NULL);
INSERT INTO `channel_message` VALUES (1031, '0fb7cedf-b648-427f-9269-ce2fdf989f06', 'AI', '### 個案收入整理\n\n#### 年收入\n- 每月廚師工作收入: 1000元 × 12 = 12000元\n- 每年幫鄰居清潔的收入: 12000元\n- 每年存款利息: 300元\n\n**總年收入**: 12000元 + 12000元 + 300元 = **24300元**\n\n#### 月收入\n**總月收入**: 24300元 ÷ 12 = **2025元**\n\n### 補助政策分析\n\n1. **中低收入戶生活補助**\n   - **條件**:\n     1. 家庭總收入分配全家人口平均每人每月低於最低生活費1.5倍（114年即2萬5,350元）。\n     2. 全家人口之現金（含存款本金、利息）、有價證券、汽車及投資合計金額每人每年未超過15萬元。\n     3. 全家人口之土地公告現值及房屋評定標準價格合計金額未超過675萬元。\n   - **分析**:\n     - 張惠萍的月收入為2025元，低於最低生活費1.5倍（25350元），符合條件。\n     - 她的年收入24300元，低於15萬元，符合條件。\n     - 由於未提供房屋及土地的具體價值，無法確定是否符合第三條件。\n   - **結論**: 由於缺乏房屋及土地的具體資料，無法確定是否符合所有條件，因此不推薦此項補助。\n\n2. **身心障礙者生活補助**\n   - **條件**:\n     1. 家庭總收入平均未達當年度每人每月最低生活費2.5倍，且未超過臺灣地區平均每人每月消費支出1.5倍者。\n     2. 全家人口動產（含存款本金、投資、有價證券）未超過一定金額。\n     3. 全家人口不動產（含房屋、土地）價值未超過臺灣省不動產限額2倍。\n   - **分析**:\n     - 張惠萍不具身心障礙身份，因此不符合申請條件。\n   - **結論**: 不推薦此項補助。\n\n3. **低收入戶生活補助**\n   - **條件**:\n     1. 戶內每人每月補助生活費新臺幣1萬3,303元。\n     2. 戶內未滿15歲兒童每人每月補助3,008元。\n   - **分析**:\n     - 張惠萍的月收入為2025元，低於低收入戶的標準（13303元），符合條件。\n   - **結論**: 由於缺乏家庭成員的具體資料，無法確定是否符合所有條件，因此不推薦此項補助。\n\n### 總結\n根據張惠萍的收入狀況，雖然她的月收入低於多項補助的標準，但由於缺乏關於家庭資產及居住狀況的具體資料，無法確定她是否符合所有條件，因此無法推薦任何政府補助。建議進一步收集相關資料以便於申請合適的補助。', NULL, NULL);
INSERT INTO `channel_message` VALUES (1032, 'f612a993-fb46-4b59-820e-2061a7861a87', 'USER', '張惠萍個案能領取的補助', NULL, NULL);
INSERT INTO `channel_message` VALUES (1033, 'f612a993-fb46-4b59-820e-2061a7861a87', 'AI', '### 個案收入整理\n\n**月收入**：張惠萍的月收入約為兩萬台幣。\n\n**年收入**：根據月收入計算，張惠萍的年收入約為240,000台幣（20,000台幣 x 12個月）。\n\n### 可用的補助政策分析\n\n1. **低收入戶生活補助**\n   - **福利說明**：針對低收入戶提供的生活補助，旨在協助其基本生活需求。\n   - **條件**：\n     - 需持有低收入戶證明。\n     - 家庭收入需低於政府規定的低收入戶標準。\n   - **符合情況**：張惠萍已經是低收入戶，並持有相關證明，因此符合申請條件。\n\n2. **醫療補助**\n   - **福利說明**：針對低收入戶提供的醫療費用補助，幫助減輕醫療負擔。\n   - **條件**：\n     - 需為低收入戶。\n     - 需提供醫療費用的相關證明。\n   - **符合情況**：張惠萍是低收入戶，符合申請條件，但需注意她目前沒有保險，可能需要提供醫療費用的相關證明。\n\n3. **社會救助金**\n   - **福利說明**：針對經濟困難的家庭提供的救助金，幫助其度過困難時期。\n   - **條件**：\n     - 需為低收入戶。\n     - 需提供家庭經濟狀況的相關證明。\n   - **符合情況**：張惠萍符合低收入戶的條件，且可提供家庭經濟狀況的證明，因此可以申請。\n\n### 總結推薦\n\n根據以上分析，張惠萍符合以下補助政策的申請條件：\n\n1. **低收入戶生活補助**\n2. **醫療補助**\n3. **社會救助金**\n\n建議張惠萍向當地社會福利機構申請上述補助，以獲得必要的經濟支持和醫療保障。', NULL, NULL);
INSERT INTO `channel_message` VALUES (1034, '85d7bf3a-c482-4515-bc80-52bccf7fdd10', 'USER', '張惠萍個案能領取的補助', NULL, NULL);
INSERT INTO `channel_message` VALUES (1035, '85d7bf3a-c482-4515-bc80-52bccf7fdd10', 'AI', '### 個案收入整理\n\n**年收入**：張惠萍的月收入約為兩萬台幣，因此年收入為：\n\\[ \n2萬台幣 \\times 12 = 24萬台幣 \n\\]\n\n**月收入**：張惠萍的月收入為兩萬台幣。\n\n### 補助政策分析\n\n根據張惠萍的個案資料，她的主要收入來源為清潔隊的臨時工，並且她的福利狀態為低收入戶。以下是可能適合她的政府補助政策：\n\n1. **低收入戶生活補助**\n   - **福利說明**：針對低收入戶提供的生活補助，旨在協助其基本生活需求。\n   - **條件**：必須為低收入戶，且家庭收入需低於政府規定的標準。\n   - **符合性**：張惠萍已經是低收入戶，符合申請條件。\n\n2. **醫療補助**\n   - **福利說明**：提供低收入戶或中低收入戶的醫療費用補助，減輕醫療負擔。\n   - **條件**：必須為低收入戶或中低收入戶，且需提供醫療費用的相關證明。\n   - **符合性**：張惠萍為低收入戶，符合申請條件。\n\n3. **社會救助金**\n   - **福利說明**：針對經濟困難的家庭提供的救助金，幫助其度過困難時期。\n   - **條件**：需為低收入戶，並經過社會局的評估。\n   - **符合性**：張惠萍為低收入戶，符合申請條件。\n\n### 總結\n\n根據以上分析，張惠萍符合以下補助政策的申請條件：\n\n- 低收入戶生活補助\n- 醫療補助\n- 社會救助金\n\n建議張惠萍向當地社會局或相關機構申請上述補助，以改善其生活狀況並獲得必要的支持。', NULL, NULL);
INSERT INTO `channel_message` VALUES (1040, '923ccd3d-a79a-4447-a7ff-34adf6dcf696', 'USER', '何志偉個案能領取的補助', NULL, NULL);
INSERT INTO `channel_message` VALUES (1041, '923ccd3d-a79a-4447-a7ff-34adf6dcf696', 'AI', '根據提供的個案資料，以下是對何志偉個案的年收入與月收入的整理，以及合適的政府補助推薦。\n\n### 1. 年收入與月收入\n- **年收入**: 由於個案資料中未提供具體的薪水金額，因此無法確定何志偉的年收入。\n- **月收入**: 同樣，由於缺乏具體的薪水數據，無法確定月收入。\n\n### 2. 補助政策分析\n由於未提供具體的補助政策內容，以下是一般可能適用的補助類型，並根據個案的情況進行分析：\n\n#### a. 低收入戶補助\n- **福利說明**: 通常針對家庭年收入低於某一標準的家庭提供經濟援助。\n- **符合條件**: 需提供家庭年收入證明，並且需被認定為中低收入戶。\n- **個案分析**: 由於無法確定何志偉的收入狀況，無法判斷是否符合此項補助的申請條件。\n\n#### b. 產假津貼\n- **福利說明**: 提供給在產假期間的配偶，通常是根據配偶的工作狀況及收入來計算。\n- **符合條件**: 配偶需在合法的產假期間，並且需有相關的工作證明。\n- **個案分析**: 何志偉的妻子目前在產假中，若其妻子符合相關條件，則可以申請此項補助。\n\n#### c. 教師專業發展補助\n- **福利說明**: 提供給在職教師進行專業發展的資助。\n- **符合條件**: 需為在職教師，並且需提供相關的進修計畫。\n- **個案分析**: 何志偉作為國中教師，若有進修計畫，則可以考慮申請此項補助。\n\n### 3. 總結\n由於缺乏具體的收入數據，無法確定何志偉是否符合低收入戶補助的條件。對於產假津貼，若其妻子符合條件則可以申請。教師專業發展補助則可根據其進修計畫進行申請。建議後續進一步訪談以獲取完整資訊，特別是收入、保險及投資情況，以便更準確地推薦合適的補助。', NULL, NULL);
INSERT INTO `channel_message` VALUES (1052, 'd26f80af-c935-43e6-99dd-6b930ea54b18', 'USER', '陳月霞個案能領取的補助', NULL, NULL);
INSERT INTO `channel_message` VALUES (1053, 'd26f80af-c935-43e6-99dd-6b930ea54b18', 'AI', '### 個案收入分析\n\n**年收入**：\n- 陳月霞的月收入約為18,000元，加上政府補助，總收入約為30,000元不到。假設政府補助為12,000元（30,000元 - 18,000元），則年收入約為：\n  - 月收入：18,000元 × 12 = 216,000元\n  - 政府補助：12,000元 × 12 = 144,000元\n  - 總年收入：約 216,000元 + 144,000元 = 360,000元\n\n**月收入**：\n- 陳月霞的月收入約為30,000元（包括擺攤和臨時清潔工的收入及政府補助）。\n\n### 補助政策分析\n\n1. **中低收入戶身心障礙者補助**：\n   - **補助金額**：輕度者每人每月補助新臺幣4,049元，中重度以上者每人每月補助新臺幣5,437元。\n   - **條件**：必須為中低收入戶，且有身心障礙者。\n   - **評估**：陳月霞的女兒為中度智能障礙者，但陳月霞並未提供中低收入戶的身份證明，因此無法確認是否符合條件。\n\n2. **中低收入戶老人補助**：\n   - **補助金額**：滿65歲老人每人每月補助新臺幣8,329元。\n   - **條件**：必須為中低收入戶，且年齡滿65歲。\n   - **評估**：陳月霞目前56歲，未滿65歲，因此不符合條件。\n\n3. **全民健保自付保險費補助**：\n   - **補助金額**：中低收入戶可補助全民健保自付保險費二分之一。\n   - **條件**：必須為中低收入戶。\n   - **評估**：由於陳月霞的中低收入戶身份未確認，因此無法推薦此項補助。\n\n4. **未滿18歲之兒童少年補助**：\n   - **補助金額**：補助全民健保自付保險費全額。\n   - **條件**：必須為未滿18歲的兒童少年。\n   - **評估**：陳月霞的女兒為成年，已超過18歲，因此不符合條件。\n\n### 總結\n\n根據以上分析，陳月霞的個案在目前的資料下，無法確定符合任何補助政策的條件。特別是中低收入戶的身份未確認，這是申請多項補助的關鍵因素。建議社工協助陳月霞進一步確認其中低收入戶的身份，並探索其他可能的社會福利資源。', NULL, NULL);
